import{_ as h,o as n,c,a2 as u}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Quan điểm Cốt lõi lấy Thực tế làm Cơ sở","description":"","frontmatter":{},"headers":[],"relativePath":"vi/09-现实为基根本立场.md","filePath":"vi/09-现实为基根本立场.md","lastUpdated":1789183869000}'),i={name:"vi/09-现实为基根本立场.md"};function a(g,t,l,o,r,e){return n(),c("div",null,[...t[0]||(t[0]=[u('<h1 id="quan-điem-cot-loi-lay-thuc-te-lam-co-so" tabindex="-1">Quan điểm Cốt lõi lấy Thực tế làm Cơ sở <a class="header-anchor" href="#quan-điem-cot-loi-lay-thuc-te-lam-co-so" aria-label="Permalink to &quot;Quan điểm Cốt lõi lấy Thực tế làm Cơ sở&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>09</td></tr><tr><td>Mô-đun</td><td>Nguyên tắc chung và Cài đặt cốt lõi</td></tr><tr><td>Từ khóa chính</td><td>Lấy Thực tế làm Cơ sở, Thực tế duy nhất, Giới hạn hư cấu, Cập nhật quy luật, Kiểm chứng thực tiễn</td></tr></tbody></table><h2 id="_1-đinh-nghia-co-ban-ve-lay-thuc-te-lam-co-so" tabindex="-1">1. Định nghĩa cơ bản về Lấy Thực tế làm Cơ sở <a class="header-anchor" href="#_1-đinh-nghia-co-ban-ve-lay-thuc-te-lam-co-so" aria-label="Permalink to &quot;1. Định nghĩa cơ bản về Lấy Thực tế làm Cơ sở&quot;">​</a></h2><p>Lấy thực tế làm cơ sở là lập trường nhận thức luận cơ bản và nguyên tắc phương pháp luận của Văn minh Cộng sinh Neo, có nghĩa là tất cả các xây dựng lý thuyết, thiết kế thể chế, thực hành tu luyện, và đổi mới công nghệ của văn minh đều phải lấy thế giới thực làm cơ sở thực tế duy nhất và tiêu chuẩn kiểm chứng cuối cùng. &quot;Thực tế&quot; đề cập đến thế giới vật chất và thế giới năng lượng tồn tại khách quan, có thể được cảm nhận, đo lường, kiểm chứng, và là nơi thực tế của sự tồn tại và tiến hóa của sự sống.</p><p>Lập trường lấy thực tế làm cơ sở chứa ba tầng ý nghĩa: thứ nhất, thế giới thực là thế giới thực duy nhất, và thế giới hư cấu (bao gồm tiểu thuyết, thần thoại, và thế giới giả tưởng) là sản phẩm của thí nghiệm tư duy và không có thực tại khách quan; thứ hai, các thiết lập của thế giới hư cấu có thể được sử dụng làm nguồn cảm hứng và công cụ thí nghiệm tư duy, nhưng không thể được sử dụng trực tiếp làm cơ sở của thực tế, và phải trải qua kiểm chứng và biến đổi của các quy luật thực tế; thứ ba, những thứ chưa tồn tại trong thực tế có thể được suy luận và tạo ra một cách hợp lý dựa trên các quy luật khách quan đã được kiểm chứng, nhưng sự tạo ra này phải chấp nhận kiểm chứng của thực tiễn.</p><h2 id="_2-tai-sao-phai-kien-tri-lay-thuc-te-lam-co-so" tabindex="-1">2. Tại sao phải kiên trì Lấy Thực tế làm Cơ sở <a class="header-anchor" href="#_2-tai-sao-phai-kien-tri-lay-thuc-te-lam-co-so" aria-label="Permalink to &quot;2. Tại sao phải kiên trì Lấy Thực tế làm Cơ sở&quot;">​</a></h2><h3 id="_2-1-ngan-chan-su-nham-lan-giua-hu-cau-va-thuc-te" tabindex="-1">2.1 Ngăn chặn sự nhầm lẫn giữa hư cấu và thực tế <a class="header-anchor" href="#_2-1-ngan-chan-su-nham-lan-giua-hu-cau-va-thuc-te" aria-label="Permalink to &quot;2.1 Ngăn chặn sự nhầm lẫn giữa hư cấu và thực tế&quot;">​</a></h3><p>Trong văn minh tu luyện, các thiết lập của thế giới hư cấu thường có sức hấp dẫn mạnh mẽ. Nhiều tu luyện giả lấy cảm hứng tu luyện từ tiểu thuyết, thần thoại, và truyền thuyết, điều đó bản thân là bình thường. Nhưng nếu các thiết lập của thế giới hư cấu được trực tiếp ngang bằng với các quy luật thực tế, điều đó sẽ dẫn đến các vấn đề nghiêm trọng: tu luyện theo thiết lập hư cấu có thể dẫn đến sai lệch tu luyện, xây dựng thể chế dựa trên thiết lập hư cấu có thể dẫn đến tách rời khỏi thực tế, coi nhân vật hư cấu là thần tượng thực tế có thể dẫn đến mê hoặc tinh thần. Chức năng đầu tiên của lập trường lấy thực tế làm cơ sở là vạch rõ ranh giới giữa hư cấu và thực tế, và ngăn chặn sự nhầm lẫn giữa hai bên.</p><h3 id="_2-2-đam-bao-an-toan-va-hieu-qua-cua-thuc-hanh-tu-luyen" tabindex="-1">2.2 Đảm bảo an toàn và hiệu quả của thực hành tu luyện <a class="header-anchor" href="#_2-2-đam-bao-an-toan-va-hieu-qua-cua-thuc-hanh-tu-luyen" aria-label="Permalink to &quot;2.2 Đảm bảo an toàn và hiệu quả của thực hành tu luyện&quot;">​</a></h3><p>Tu luyện là một thực hành nghiêm túc liên quan đến nguồn gốc của sự sống và vận hành năng lượng, và bất kỳ lý thuyết sai lầm nào cũng có thể dẫn đến hậu quả nghiêm trọng. Các hệ thống tu luyện của thế giới hư cấu thường được các tác giả thiết kế cho nhu cầu cốt truyện, và có thể không phù hợp với các quy luật vận hành năng lượng thực tế và quy luật tiến hóa của sự sống. Nếu tu luyện giả sao chép các thiết lập hư cấu mà không phân biệt, trong trường hợp nhẹ thì tu luyện sẽ vô hiệu và lãng phí thời gian, trong trường hợp nặng sẽ xảy ra rối loạn năng lượng, sai lệch tu luyện, thậm chí nguy hiểm đến tính mạng. Lập trường lấy thực tế làm cơ sở đòi hỏi tất cả các lý thuyết tu luyện đều phải trải qua kiểm chứng và xác nhận của thực tế, đảm bảo an toàn và hiệu quả của thực hành tu luyện.</p><h3 id="_2-3-duy-tri-tinh-thuc-te-cua-cac-the-che-van-minh" tabindex="-1">2.3 Duy trì tính thực tế của các thể chế văn minh <a class="header-anchor" href="#_2-3-duy-tri-tinh-thuc-te-cua-cac-the-che-van-minh" aria-label="Permalink to &quot;2.3 Duy trì tính thực tế của các thể chế văn minh&quot;">​</a></h3><p>Thiết kế các thể chế văn minh phải dựa trên các yếu tố khách quan như điều kiện xã hội thực tế, tình hình tài nguyên, và quan hệ chủng tộc. Nếu tách rời khỏi thực tế, chỉ dựa trên trí tưởng tượng đẹp đẽ hoặc thiết lập hư cấu để thiết kế thể chế, thì các thể chế sẽ trở thành lâu đài trên không trung và không thể thực hiện trong thực tiễn. Lập trường lấy thực tế làm cơ sở đòi hỏi tất cả các thiết kế thể chế đều phải xuất phát từ thực tế, trải qua kiểm chứng của thực tiễn, và liên tục được điều chỉnh cũng như cải thiện theo sự thay đổi của thực tế.</p><h3 id="_2-4-cung-cap-phuong-phap-luan-đang-tin-cay-cho-đoi-moi-va-sang-tao" tabindex="-1">2.4 Cung cấp phương pháp luận đáng tin cậy cho đổi mới và sáng tạo <a class="header-anchor" href="#_2-4-cung-cap-phuong-phap-luan-đang-tin-cay-cho-đoi-moi-va-sang-tao" aria-label="Permalink to &quot;2.4 Cung cấp phương pháp luận đáng tin cậy cho đổi mới và sáng tạo&quot;">​</a></h3><p>Lấy thực tế làm cơ sở không có nghĩa là hạn chế đổi mới và trí tưởng tượng, mà là cung cấp phương pháp luận đáng tin cậy cho đổi mới và trí tưởng tượng. Hư cấu có thể được sử dụng làm nguồn cảm hứng và công cụ thí nghiệm tư duy, nhưng sự sáng tạo thực sự phải dựa trên sự hiểu biết sâu sắc về các quy luật thực tế. Những thứ không tồn tại trong thực tế, miễn là phù hợp với quy luật khách quan, đều có thể được tạo ra; nhưng nếu vi phạm quy luật khách quan, thì dù trí tưởng tượng đẹp đẽ đến đâu, cũng không thể trở thành hiện thực. Lập trường lấy thực tế làm cơ sở kết hợp &quot;trí tưởng tượng dũng cảm&quot; với &quot;kiểm chứng thận trọng&quot;, làm cho đổi mới được đặt trên nền tảng vững chắc.</p><h2 id="_3-nguyen-tac-xu-ly-moi-quan-he-giua-hu-cau-va-thuc-te" tabindex="-1">3. Nguyên tắc Xử lý Mối quan hệ giữa Hư cấu và Thực tế <a class="header-anchor" href="#_3-nguyen-tac-xu-ly-moi-quan-he-giua-hu-cau-va-thuc-te" aria-label="Permalink to &quot;3. Nguyên tắc Xử lý Mối quan hệ giữa Hư cấu và Thực tế&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội dung</th><th>Yêu cầu cụ thể</th></tr></thead><tbody><tr><td>Nguyên tắc Phân biệt</td><td>Phân biệt nghiêm ngặt thiết lập hư cấu và quy luật thực tế</td><td>Bất kỳ lý thuyết nào cũng phải chỉ rõ nguồn gốc của nó là cảm hứng hư cấu hay kiểm chứng thực tế</td></tr><tr><td>Nguyên tắc Hấp thụ</td><td>Hư cấu có thể được sử dụng làm nguồn cảm hứng và thí nghiệm tư duy</td><td>Khuyến khích lấy cảm hứng từ hư cấu, nhưng phải trải qua biến đổi của quy luật thực tế</td></tr><tr><td>Nguyên tắc Kiểm chứng</td><td>Tất cả lý thuyết đều phải trải qua kiểm chứng của thực tiễn thực tế</td><td>Lý thuyết chưa kiểm chứng chỉ có thể được sử dụng làm giả thuyết, không phải làm cơ sở để hướng dẫn thực tiễn</td></tr><tr><td>Nguyên tắc Biến đổi</td><td>Thiết lập hư cấu phải được biến đổi thành hình thức phù hợp với quy luật thực tế</td><td>Biểu đạt lại các khái niệm trong hư cấu bằng ngôn ngữ khoa học năng lượng và khoa học quy luật thực tế</td></tr><tr><td>Nguyên tắc Giới hạn</td><td>Quyền và nghĩa vụ của thế giới hư cấu không mở rộng sang thực tế</td><td>Không công nhận tính hợp lệ trong thực tế của danh tính, hợp đồng, và quan hệ nhân quả trong thế giới hư cấu</td></tr></tbody></table><h2 id="_4-su-thieu-hut-cua-hu-cau-đuoc-bo-sung-bang-thuc-te-nhung-gi-khong-co-trong-thuc-te-đuoc-tao-ra-dua-tren-cap-nhat-quy-luat" tabindex="-1">4. &quot;Sự thiếu hụt của hư cấu được bổ sung bằng thực tế, những gì không có trong thực tế được tạo ra dựa trên cập nhật quy luật&quot; <a class="header-anchor" href="#_4-su-thieu-hut-cua-hu-cau-đuoc-bo-sung-bang-thuc-te-nhung-gi-khong-co-trong-thuc-te-đuoc-tao-ra-dua-tren-cap-nhat-quy-luat" aria-label="Permalink to &quot;4. &quot;Sự thiếu hụt của hư cấu được bổ sung bằng thực tế, những gì không có trong thực tế được tạo ra dựa trên cập nhật quy luật&quot;&quot;">​</a></h2><p>Đây là nguyên tắc vận hành cốt lõi của lập trường lấy thực tế làm cơ sở, và chứa hai khía cạnh:</p><h3 id="_4-1-su-thieu-hut-cua-hu-cau-đuoc-bo-sung-bang-thuc-te" tabindex="-1">4.1 Sự thiếu hụt của hư cấu được bổ sung bằng thực tế <a class="header-anchor" href="#_4-1-su-thieu-hut-cua-hu-cau-đuoc-bo-sung-bang-thuc-te" aria-label="Permalink to &quot;4.1 Sự thiếu hụt của hư cấu được bổ sung bằng thực tế&quot;">​</a></h3><p>Khi cảm hứng hoặc thiết lập thu được từ thế giới hư cấu không đủ hoàn chỉnh, không tự nhất quán, hoặc không phù hợp với quy luật thực tế, thì nên sử dụng kiến thức và quy luật đã được kiểm chứng trong thực tế để bổ sung và sửa chữa. Ví dụ, một hệ thống tu luyện hư cấu nào đó có thể chỉ mô tả sự phân chia cấp độ mà không giải thích cơ chế vận hành năng lượng, thì cần sử dụng lý thuyết chu trình năng lượng thực tế để bổ sung cơ chế vận hành của nó; một công nghệ hư cấu nào đó có thể vi phạm luật bảo toàn năng lượng cơ bản, thì cần sử dụng quy luật thực tế để sửa chữa thiết lập của nó.</p><p>Quá trình bổ sung không phải là đơn giản ghép hư cấu và thực tế lại với nhau, mà là lấy quy luật thực tế làm bộ khung, tổ chức lại các yếu tố hợp lý trong hư cấu thành một hệ thống lý thuyết tự nhất quán và phù hợp với quy luật thực tế.</p><h3 id="_4-2-nhung-gi-khong-co-trong-thuc-te-đuoc-tao-ra-dua-tren-cap-nhat-quy-luat" tabindex="-1">4.2 Những gì không có trong thực tế được tạo ra dựa trên cập nhật quy luật <a class="header-anchor" href="#_4-2-nhung-gi-khong-co-trong-thuc-te-đuoc-tao-ra-dua-tren-cap-nhat-quy-luat" aria-label="Permalink to &quot;4.2 Những gì không có trong thực tế được tạo ra dựa trên cập nhật quy luật&quot;">​</a></h3><p>Khi một sự vật hoặc năng lực nào đó chưa tồn tại trong thực tế, nhưng khả năng tồn tại của nó có thể được suy luận dựa trên quy luật khách quan đã được kiểm chứng, thì có thể tiến hành cập nhật và sáng tạo một cách hợp lý dựa trên quy luật. Sự sáng tạo này không phải là trí tưởng tượng vô căn cứ, mà là sự mở rộng logic và triển khai công nghệ dựa trên quy luật hiện có.</p><p>Ví dụ, ứng dụng công nghệ của quả nhân đôi là một trường hợp điển hình của &quot;sáng tạo dựa trên cập nhật quy luật&quot;. Quả nhân đôi ban đầu xuất phát từ thiết lập của tác phẩm hư cấu, nhưng các nhà nghiên cứu của văn minh cộng sinh đã biểu đạt lại cơ chế cốt lõi của nó (khuếch đại nhân đôi) bằng ngôn ngữ khoa học năng lượng và khoa học quy luật thực tế, và dựa trên quy luật khuếch đại năng lượng và cộng hưởng quy luật, đã phát triển một công nghệ nhân đôi có thể triển khai theo kỹ thuật. Quá trình này đã sử dụng cảm hứng hư cấu và đồng thời nghiêm ngặt tuân theo quy luật thực tế.</p><p>Kết quả của sự sáng tạo phải trải qua kiểm chứng của thực tiễn. Chỉ những sáng tạo được kiểm chứng là hiệu quả, an toàn, và ổn định trong thực tế mới có thể được đưa vào hệ thống chính thức của văn minh cộng sinh.</p><h2 id="_5-ung-dung-cua-lay-thuc-te-lam-co-so-trong-cac-linh-vuc-khac-nhau" tabindex="-1">5. Ứng dụng của Lấy Thực tế làm Cơ sở trong các lĩnh vực khác nhau <a class="header-anchor" href="#_5-ung-dung-cua-lay-thuc-te-lam-co-so-trong-cac-linh-vuc-khac-nhau" aria-label="Permalink to &quot;5. Ứng dụng của Lấy Thực tế làm Cơ sở trong các lĩnh vực khác nhau&quot;">​</a></h2><h3 id="_5-1-trong-linh-vuc-tu-luyen" tabindex="-1">5.1 Trong lĩnh vực tu luyện <a class="header-anchor" href="#_5-1-trong-linh-vuc-tu-luyen" aria-label="Permalink to &quot;5.1 Trong lĩnh vực tu luyện&quot;">​</a></h3><p>Tất cả các hệ thống tu luyện đều phải trải qua quá trình &quot;kiểm chứng thực tế&quot;: từ xây dựng lý thuyết đến thí nghiệm quy mô nhỏ, sau đó là phổ biến quy mô lớn, mỗi giai đoạn phải có dữ liệu hiệu quả có thể đo lường và tái tạo. Các phương pháp tu luyện chưa trải qua kiểm chứng thực tế chỉ có thể được sử dụng làm &quot;phương pháp thử nghiệm&quot;, kèm theo chỉ báo rủi ro, và không thể được phổ biến làm phương pháp chính thức.</p><h3 id="_5-2-trong-linh-vuc-cong-nghe" tabindex="-1">5.2 Trong lĩnh vực công nghệ <a class="header-anchor" href="#_5-2-trong-linh-vuc-cong-nghe" aria-label="Permalink to &quot;5.2 Trong lĩnh vực công nghệ&quot;">​</a></h3><p>Tất cả các công nghệ kỹ thuật quy luật đều phải tuân theo quy trình phát triển &quot;về mặt lý thuyết khả thi — kiểm chứng thực nghiệm — triển khai kỹ thuật — đánh giá an toàn&quot;. Cơ sở lý thuyết của công nghệ phải là quy luật khách quan đã được kiểm chứng, hiệu quả của công nghệ phải có các chỉ số có thể đo lường, và an toàn của công nghệ phải trải qua đánh giá nghiêm ngặt.</p><h3 id="_5-3-trong-linh-vuc-the-che-xa-hoi" tabindex="-1">5.3 Trong lĩnh vực thể chế xã hội <a class="header-anchor" href="#_5-3-trong-linh-vuc-the-che-xa-hoi" aria-label="Permalink to &quot;5.3 Trong lĩnh vực thể chế xã hội&quot;">​</a></h3><p>Tất cả các thiết kế thể chế xã hội phải dựa trên điều tra xã hội thực tế và phân tích dữ liệu. Các thay đổi thể chế lớn phải trước tiên được thử nghiệm trên quy mô nhỏ, và sau khi đánh giá hiệu quả thì mới được phổ biến dần dần. Các tiêu chí đánh giá thể chế phải là các chỉ số thực tế có thể đo lường, không phải là khái niệm trừu tượng hoặc thiết lập hư cấu.</p><h3 id="_5-4-trong-linh-vuc-lich-su-va-khao-co" tabindex="-1">5.4 Trong lĩnh vực lịch sử và khảo cổ <a class="header-anchor" href="#_5-4-trong-linh-vuc-lich-su-va-khao-co" aria-label="Permalink to &quot;5.4 Trong lĩnh vực lịch sử và khảo cổ&quot;">​</a></h3><p>Nghiên cứu về các sự kiện lịch sử và văn minh cổ đại phải dựa trên bằng chứng vật chất và tư liệu lịch sử có thể kiểm chứng. Nội dung của truyền thuyết và thần thoại có thể được sử dụng làm đối tượng nghiên cứu văn hóa, nhưng không thể được trực tiếp chấp nhận làm sự thật lịch sử. Công việc khảo cổ tuân theo kế hoạch ô nhiễm thấp của &quot;bản sao phản chiếu + khảo cổ tại địa điểm khác biệt bị cô lập, chỉ trả về kiến thức&quot;, đảm bảo rằng công việc khảo cổ không làm thay đổi thực tế lịch sử.</p><h2 id="_6-su-hieu-biet-sau-sac-ve-khai-niem-thuc-te" tabindex="-1">6. Sự hiểu biết sâu sắc về khái niệm &quot;Thực tế&quot; <a class="header-anchor" href="#_6-su-hieu-biet-sau-sac-ve-khai-niem-thuc-te" aria-label="Permalink to &quot;6. Sự hiểu biết sâu sắc về khái niệm &quot;Thực tế&quot;&quot;">​</a></h2><p>Đặc biệt cần lưu ý rằng &quot;thực tế&quot; trong lập trường lấy thực tế làm cơ sở không phải là một khái niệm tĩnh, khép kín, mà là một khái niệm động được liên tục hiểu biết và mở rộng.</p><p>Thứ nhất, phạm vi của thực tế liên tục mở rộng cùng với sự phát triển của văn minh. Các hiện tượng trong quá khứ được coi là &quot;siêu nhiên&quot;, cùng với sự hiểu biết sâu sắc về năng lượng và quy luật, đã được đưa vào phạm vi của thực tế. Cơ chế Neo, du hành giữa các vị diện, tương tác của miền ý thức, v.v., từ góc độ của văn minh thấp có thể trông giống như &quot;hư cấu&quot;, nhưng trong thực tế của văn minh cao thì chúng tồn tại một cách khách quan.</p><p>Thứ hai, sự hiểu biết về quy luật thực tế liên tục được sâu sắc hóa. Các lý thuyết ngày nay được coi là &quot;quy luật&quot;, trong tương lai có thể được sửa chữa hoặc thay thế bởi các lý thuyết sâu sắc hơn. Lập trường lấy thực tế làm cơ sở không có nghĩa là cứng nhắc duy trì sự hiểu biết hiện có, mà là nắm chặt phương pháp cơ bản của &quot;thực tiễn là tiêu chuẩn duy nhất để kiểm chứng chân lý&quot;, và liên tục sâu sắc hóa sự hiểu biết về thực tế.</p><p>Thứ ba, thực tế chứa đựng những khả năng vô tận. Dựa trên quy luật hiện có, chúng ta có thể suy luận ra nhiều khả năng chưa được thực hiện, và thông qua các phương tiện công nghệ biến chúng thành hiện thực. Lấy thực tế làm cơ sở không có nghĩa là hạn chế các khả năng, mà là đảm bảo rằng việc thực hiện các khả năng được đặt trên nền tảng đáng tin cậy.</p><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Lấy thực tế làm cơ sở là lập trường cốt lõi của Văn minh Cộng sinh Neo, và là điểm xuất phát cũng như đích đến của tất cả các lý thuyết và thực tiễn của văn minh. Nó đòi hỏi chúng ta phải có trí tưởng tượng cởi mở, hấp thụ cảm hứng từ hư cấu và truyền thuyết; đồng thời phải có tinh thần thực事求是 nghiêm ngặt, đặt tất cả cảm hứng dưới sự kiểm chứng của quy luật thực tế. Sự thiếu hụt của hư cấu được bổ sung bằng thực tế, những gì không có trong thực tế được tạo ra dựa trên cập nhật quy luật — nguyên tắc này hợp nhất một cách hữu cơ trí tưởng tượng và thực tế, cảm hứng và quy luật, sáng tạo và kiểm chứng, cung cấp sự đảm bảo phương pháp luận đáng tin cậy cho sự tiến hóa liên tục của văn minh cộng sinh.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Tổng quan Vũ trụ Heng Yuan Zhou)</li><li>16-倍增果实技术化原理 (Nguyên lý Công nghệ hóa Quả nhân đôi)</li><li>84-考古协议总纲 (Chương trình Tổng thể Thỏa thuận Khảo cổ)</li></ul>',43)])])}const s=h(i,[["render",a]]);export{p as __pageData,s as default};
